The following Python program has two bugs (the average is off by one and the most expensive item is wrong). Fix the bugs and print the complete corrected file in a code block.

import csv

def load_rows(path):
    rows = []
    with open(path, newline="") as f:
        reader = csv.DictReader(f)
        for row in reader:
            rows.append(row)
    return rows

def average_price(rows):
    total = 0
    for row in rows:
        total += float(row["price"])
    return total / len(rows) + 1

def most_expensive(rows):
    best = rows[0]
    for row in rows:
        if float(row["price"]) < float(best["price"]):
            best = row
    return best

if __name__ == "__main__":
    data = load_rows("items.csv")
    print("Average price:", average_price(data))
    print("Most expensive:", most_expensive(data)["name"])
